<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
const props=defineProps<{page:string}>()
const stats=ref<any>({}),materials=ref<any[]>([]),results=ref<any[]>([]),facts=ref<any[]>([]),conflicts=ref<any[]>([])
const selected=ref(''),detail=ref<any>(null),error=ref(''),busy=ref(false),dataLoading=ref(false),events=ref<any[]>([]),connected=ref(false)
const uploadFile=ref<File|null>(null),source=ref('SIMULATOR'),authorized=ref(false),authorization=ref(''),description=ref(''),version=ref(''),server=ref(''),captured=ref('')
const interval=ref(2),maxFrames=ref(20),roiKind=ref('OCR_TEXT'),roiText=ref(''),reviewStatus=ref('PENDING'),reviewTarget=ref<any>(null),reviewAction=ref('confirm'),reviewField=ref('visible_text'),reviewValue=ref(''),reviewer=ref('本地审核员'),rationale=ref(''),evidence=ref<any>(null)
const annotations=ref<any[]>([]),annotationKind=ref('SCENE_REGION'),annotationJson=ref('[]'),revision=ref(0),undoStack=ref<string[]>([]),drag=ref<number[]|null>(null),annotationReason=ref('人工标注当前截图的可见部分')
const titles:Record<string,string>={'#/observations':'场景观察中心','#/media':'截图与录像管理','#/analysis':'OCR 和视觉分析','#/annotations':'九星地图标注','#/boss-samples':'BOSS 样本管理','#/review':'知识库补全审核','#/twins':'数字孪生场景管理','#/evidence':'数据证据详情'}
const annotationNames:Record<string,string>={SCENE_REGION:'场景区域',PLAYER:'角色',MONSTER:'怪物',BOSS:'BOSS',OBSTACLE:'可见障碍',WALKABLE_REGION:'可见通行区域',ENTRY:'入口',EXIT:'出口',MECHANIC:'机关',TEXT_REGION:'提示文字',ITEM:'可见物品'}
const title=computed(()=>titles[props.page]||'场景观察中心')
const preview=computed(()=>selected.value?'/api/observations/media/'+selected.value+'/preview':'')
const imageMedia=computed(()=>detail.value&&['PNG','JPG'].includes(detail.value.file_type))
const filteredResults=computed(()=>results.value.filter(r=>(!reviewStatus.value||r.status===reviewStatus.value)&&(props.page!=='#/boss-samples'||r.kind==='BOSS_NAME')))
const displayedAnnotations=computed(()=>annotations.value.filter(a=>a.coordinate_system==='SCREEN_PIXEL'))
const twinRows=ref<any[]>([]),twinEvidence=ref<any[]>([])
const twinEditor=ref(JSON.stringify({scene_id:'nine-star-research',dungeon_id:'alama',game_version:null,evidence_ids:[],map_regions:[],navigation_nodes:[],obstacles:[],enemy_definitions:[],stage_triggers:[],visible_mechanics:[],reward_definitions:[],confidence:null,validation_status:'DRAFT',base_revision:0,author:'本地研究员',reason:'创建独立九星研究草稿'},null,2))
function editTwin(row:any){const {execution_environment,map_coverage,current_game_verified,...config}=row.configuration;twinEditor.value=JSON.stringify({...config,base_revision:row.revision,author:'本地研究员',reason:'修改独立研究场景，保留历史版本'},null,2)}
async function saveTwin(){await operation(()=>request('twins','POST',JSON.parse(twinEditor.value)))}
let stream:EventSource
async function request(path:string,method='GET',body?:any){const r=await fetch('/api/observations/'+path,{method,headers:method==='GET'?{}:{'X-Agent-Control':'local-console',...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:method==='GET'?undefined:body instanceof FormData?body:JSON.stringify(body)});if(!r.ok)throw new Error(await r.text());return r.json()}
async function load(){dataLoading.value=true;try{const [s,m,r,f,c]=await Promise.all(['status','media','results','facts','conflicts'].map(p=>request(p)));const [tw,te]=await Promise.all([request('twins'),request('twins/evidence')]);twinRows.value=tw.items;twinEvidence.value=te.items;stats.value=s;materials.value=m.items;results.value=r.items;facts.value=f.items;conflicts.value=c.items;if(!selected.value&&m.items.length)selected.value=m.items[0].id;if(selected.value)await choose()}catch(e){error.value=String(e)}finally{dataLoading.value=false}}
async function choose(){if(!selected.value)return;detail.value=await request('media/'+selected.value);const last=detail.value.annotations[0];annotations.value=last?.annotations||[];revision.value=last?.revision||0;annotationJson.value=JSON.stringify(annotations.value,null,2);undoStack.value=[]}
async function operation(fn:()=>Promise<any>){busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function upload(){await operation(async()=>{if(!uploadFile.value)throw new Error('请选择文件');const form=new FormData();form.append('file',uploadFile.value);form.append('metadata',JSON.stringify({authorized:authorized.value,source_type:source.value,authorization_note:authorization.value,description:description.value,game_version:version.value||null,server_info:server.value||null,captured_at:captured.value?new Date(captured.value).toISOString():null}));const m=await request('media','POST',form);selected.value=m.id})}
async function extract(){await operation(()=>request('media/'+selected.value+'/extract','POST',{interval_seconds:interval.value,max_frames:maxFrames.value}))}
async function analyze(){await operation(()=>request('media/'+selected.value+'/analyze','POST',{regions:roiText.value?[{kind:roiKind.value,region:JSON.parse(roiText.value)}]:null}))}
function beginReview(r:any){reviewTarget.value=r;reviewAction.value=r.status==='UNKNOWN'?'correct':'confirm';reviewValue.value=JSON.stringify(r.value);rationale.value='';reviewField.value=r.kind==='GAME_COORDINATE'?'entry_coordinates':r.kind==='BOSS_NAME'?'boss_name':'visible_text'}
async function saveReview(){await operation(async()=>{await request('results/'+reviewTarget.value.id+'/review','POST',{action:reviewAction.value,reviewer:reviewer.value,rationale:rationale.value,field:reviewField.value,corrected_value:reviewAction.value==='correct'?JSON.parse(reviewValue.value):null});reviewTarget.value=null})}
async function showEvidence(r:any){evidence.value=await request('results/'+r.id);selected.value=r.media_id;await choose()}
function point(event:PointerEvent){const b=(event.currentTarget as SVGElement).getBoundingClientRect();return [Math.max(0,Math.min(detail.value.width,(event.clientX-b.left)*detail.value.width/b.width)),Math.max(0,Math.min(detail.value.height,(event.clientY-b.top)*detail.value.height/b.height))]}
function drawStart(e:PointerEvent){if(!dataLoading.value&&imageMedia.value&&props.page==='#/annotations'){drag.value=point(e);(e.currentTarget as Element).setPointerCapture(e.pointerId)}}
function drawEnd(e:PointerEvent){if(!drag.value)return;const end=point(e);const [x,y]=drag.value;drag.value=null;const region=[Math.floor(Math.min(x,end[0])),Math.floor(Math.min(y,end[1])),Math.floor(Math.abs(x-end[0])),Math.floor(Math.abs(y-end[1]))];if(region[2]<2||region[3]<2)return;undoStack.value.push(JSON.stringify(annotations.value));annotations.value.push({kind:annotationKind.value,coordinate_system:'SCREEN_PIXEL',region,label:annotationNames[annotationKind.value],coverage:'VISIBLE_PORTION_ONLY'});annotationJson.value=JSON.stringify(annotations.value,null,2)}
function applyAnnotationJson(){try{const next=JSON.parse(annotationJson.value);if(!Array.isArray(next))throw new Error('标注必须为数组');undoStack.value.push(JSON.stringify(annotations.value));annotations.value=next;error.value=''}catch(e){error.value=String(e)}}
function undo(){const before=undoStack.value.pop();if(before){annotations.value=JSON.parse(before);annotationJson.value=JSON.stringify(annotations.value,null,2)}}
async function saveAnnotations(){await operation(()=>request('media/'+selected.value+'/annotations','POST',{annotations:JSON.parse(annotationJson.value),author:reviewer.value,reason:annotationReason.value,base_revision:revision.value}))}
function restoreRevision(id:string){const record=detail.value.annotations.find((r:any)=>r.id===id);if(record){undoStack.value.push(JSON.stringify(annotations.value));annotations.value=JSON.parse(JSON.stringify(record.annotations));annotationJson.value=JSON.stringify(annotations.value,null,2)}}
onMounted(async()=>{await load();const cursor=Number(sessionStorage.getItem('observation-log-cursor')||0);stream=new EventSource('/api/logs/stream?after='+cursor);stream.onopen=()=>connected.value=true;stream.onerror=()=>connected.value=false;stream.onmessage=e=>{const row=JSON.parse(e.data);sessionStorage.setItem('observation-log-cursor',String(row.id));if(row.stage==='OBSERVATION'){events.value.push(row);if(events.value.length>100)events.value.shift()}}})
onUnmounted(()=>stream?.close())
watch(()=>props.page,()=>{error.value=''})
</script>
<template>
<div class="shell"><aside><div class="logo">M<span> / </span>A</div><h3>魔域智能 Agent</h3><small>OBSERVATION LAB · V1.2</small><nav class="observation-nav"><a href="/#/console">◈ 运行控制台</a><a href="/#/knowledge">◇ 官网知识库</a><a href="/#/research">◆ 九星副本运行</a><a v-for="(label,path) in titles" :key="path" :href="'/'+path" :class="{active:page===path}">{{label}}</a></nav><div class="aside-note"><b>OBSERVATION</b><p>用户授权资料 · 被动分析<br>SIMULATOR 样本单独标记</p></div></aside>
<main><header><div><div class="eyebrow">EVIDENCE FIRST · PASSIVE RESEARCH</div><h1>{{title}}</h1><p>原图 → 识别 → 人工审核 → 可见值事实 · 独立研究数据集</p></div><button @click="load">刷新数据</button></header><div class="notice">OBSERVATION 被动资料研究 · 未知版本保持 NULL。OCR 置信度不等于识别准确率，单张图不代表完整地图或官服机制。</div>
<div class="metrics"><article><label>原始资料 / 抽取帧</label><strong>{{stats.materials??0}} <i>/ {{stats.frames??0}}</i></strong><small>受管文件与 SHA-256</small></article><article><label>游戏资料 / 模拟器资料</label><strong>{{stats.game_materials??0}} <i>/ {{stats.simulator_materials??0}}</i></strong><small>按导入来源分别统计</small></article><article><label>待审核 / UNKNOWN</label><strong>{{stats.pending??0}} <i>/ {{stats.unknown_results??0}}</i></strong><small>不自动确认识别结果</small></article><article><label>观察事实 / 模拟假设</label><strong>{{stats.observed_facts??0}} <i>/ {{stats.simulated_assumptions??0}}</i></strong><small>人工审核后单独保存</small></article></div>
<p v-if="error" class="error">{{error}}</p><p v-if="busy" class="notice">正在执行真实导入、识别或保存操作，请稍候…</p>
<section v-if="page==='#/media'||page==='#/observations'" class="panel"><div class="panel-title"><h2>导入授权截图 / 录像</h2><span>PNG/JPG ≤20MB · MP4/WebM ≤100MB / 10分钟</span></div><div class="observation-form"><input type="file" accept=".png,.jpg,.jpeg,.mp4,.webm" @change="uploadFile=($event.target as HTMLInputElement).files?.[0]||null"><label>数据来源<select v-model="source"><option value="SIMULATOR">SIMULATOR 自建模拟器样本</option><option value="GAME_OBSERVATION">GAME_OBSERVATION 用户授权游戏画面</option></select></label><label>游戏版本（未知留空）<input v-model="version" placeholder="不自动填入版本"></label><label>服务器信息（有依据才填）<input v-model="server"></label><label>画面采集时间（未知留空）<input v-model="captured" type="datetime-local"></label><label>用户说明<input v-model="description"></label><label class="full">使用授权记录<textarea v-model="authorization" placeholder="说明所有权或授权依据；自建素材写明生成方式"></textarea></label><label><input v-model="authorized" type="checkbox"> 我拥有此资料或已获准使用</label><button class="primary" :disabled="busy||!authorized||!uploadFile" @click="upload">导入资料</button></div></section>
<section v-if="materials.length" class="panel history"><div class="panel-title"><h2>资料与原图</h2><select v-model="selected" @change="choose"><option v-for="m in materials" :key="m.id" :value="m.id">{{m.filename}} · {{m.source_type}} · {{m.id.slice(0,8)}}</option></select></div><div v-if="detail" class="media-detail"><div class="media-preview"><img v-if="page!=='#/annotations'&&page!=='#/analysis'" :src="preview" alt="导入资料的真实预览"><div v-else class="annotation-canvas"><img :src="preview" alt="人工标注原图"><svg :viewBox="'0 0 '+detail.width+' '+detail.height" @pointerdown="drawStart" @pointerup="drawEnd"><g v-for="(a,i) in displayedAnnotations" :key="i"><rect :x="a.region[0]" :y="a.region[1]" :width="a.region[2]" :height="a.region[3]"/><text :x="a.region[0]+3" :y="a.region[1]+14">{{a.label||a.kind}}</text></g><g v-if="page==='#/analysis'" v-for="r in detail.observations" :key="r.id"><rect :x="r.region[0]" :y="r.region[1]" :width="r.region[2]" :height="r.region[3]"/></g></svg></div></div><div class="media-metadata"><p>原始 ID：{{detail.id}}</p><p>来源 {{detail.source_type}} · {{detail.verification_status}}</p><p>分辨率 {{detail.width}} × {{detail.height}} · {{detail.file_type}}</p><p>版本 {{detail.game_version??'UNKNOWN'}} · 服务器 {{detail.server_info??'UNKNOWN'}}</p><p>采集 {{detail.captured_at??'UNKNOWN'}} · 导入 {{new Date(detail.imported_at).toLocaleString()}}</p><p>授权 {{detail.authorization_note}}</p><p>说明 {{detail.description}}</p><code>SHA-256 {{detail.sha256}}</code><p><a :href="'/api/observations/media/'+detail.id+'/file'">下载原始文件</a></p><template v-if="['MP4','WEBM'].includes(detail.file_type)"><p>时长 {{detail.duration?.toFixed(2)}} 秒</p><label>抽帧间隔<input v-model.number="interval" type="number" min="0.5"></label><label>最多帧数<input v-model.number="maxFrames" type="number" min="1" max="60"></label><button :disabled="busy||dataLoading" @click="extract">执行间隔抽帧</button><p>每视频累计上限60帧 / 100MB；相似帧去重。</p></template></div></div></section>
<p v-else class="empty">尚无资料。请导入你拥有或获准使用的画面；不预置虚构官服观察。</p>
<section v-if="page==='#/analysis' && imageMedia" class="panel history"><div class="panel-title"><h2>OCR 与视觉分析</h2><span>原始结果先进入待审核观察</span></div><div class="observation-form"><label>区域识别用途<select v-model="roiKind"><option v-for="k in ['OCR_TEXT','GAME_COORDINATE','MAP_NAME','PLAYER','MONSTER_NAME','BOSS_NAME','QUEST_TEXT','INVENTORY_TEXT']" :key="k">{{k}}</option></select></label><label>原图屏幕区域<input v-model="roiText" placeholder="留空识别全图，或 [x,y,width,height]"></label><button class="primary" :disabled="busy||dataLoading" @click="analyze">执行本地视觉分析</button><p>角色定位无法从文字框推断。官服无角色模板时保持 UNKNOWN，位置由人工标注补充。</p></div><div class="table-wrap"><table><thead><tr><th>类型</th><th>原始文字 / 值</th><th>屏幕区域</th><th>模型置信度</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="r in detail.observations" :key="r.id"><td>{{r.kind}}</td><td>{{r.raw_text||r.value||'UNKNOWN'}}</td><td>{{r.region.join(', ')}}</td><td>{{r.confidence===null?'UNKNOWN':r.confidence.toFixed(3)}}</td><td>{{r.status}}</td><td><button @click="showEvidence(r)">证据</button></td></tr></tbody></table></div></section>
<section v-if="page==='#/annotations'&&imageMedia" class="panel history"><div class="panel-title"><h2>可见部分人工标注</h2><span>SCREEN_PIXEL / MAP_PIXEL / GAME_COORDINATE 分离</span></div><div class="observation-form"><label>画框类别<select v-model="annotationKind"><option v-for="(name,key) in annotationNames" :key="key" :value="key">{{name}}</option></select></label><label>标注人<input v-model="reviewer"></label><label class="full">修改依据<input v-model="annotationReason"></label><button @click="undo" :disabled="!undoStack.length">撤销本地修改</button><button @click="saveAnnotations" :disabled="busy||dataLoading">保存新版本（当前 {{revision}}）</button><label>加载历史版本<select @change="restoreRevision(($event.target as HTMLSelectElement).value)"><option value="">选择版本，保存后形成新版本</option><option v-for="r in detail.annotations" :key="r.id" :value="r.id">版本 {{r.revision}} · {{r.author}}</option></select></label><label class="full">标注 JSON（地图/游戏坐标必须添加 coordinate_basis，不能自动从截图换算）<textarea class="json-editor" v-model="annotationJson" @change="applyAnnotationJson"></textarea></label><p class="full">在原图拖动绘制屏幕区域。可通行标注仅表示截图可见部分，不能推断完整地图。</p></div></section>
<section v-if="['#/review','#/boss-samples','#/evidence'].includes(page)" class="panel history"><div class="panel-title"><h2>{{page==='#/boss-samples'?'BOSS 名称画面样本':'观察结果与人工审核'}}</h2><select v-model="reviewStatus"><option value="">全部状态</option><option>PENDING</option><option>UNKNOWN</option><option>CONFIRMED</option><option>REJECTED</option><option>ERROR</option></select></div><div class="table-wrap"><table><thead><tr><th>观察 ID / 类型</th><th>原始结果</th><th>来源 / 版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in filteredResults" :key="r.id"><td>{{r.id.slice(0,8)}} · {{r.kind}}</td><td>{{r.raw_text||JSON.stringify(r.value)||'UNKNOWN'}}</td><td>{{r.source_type}} / {{r.game_version??'UNKNOWN'}}</td><td>{{r.status}}</td><td><button @click="showEvidence(r)">原图证据</button> <button v-if="!['CONFIRMED','REJECTED'].includes(r.status)" @click="beginReview(r)">审核 / 纠错</button></td></tr></tbody></table><p v-if="!filteredResults.length" class="empty">没有符合当前筛选条件的实际观察</p></div></section>
<section v-if="reviewTarget" class="panel history"><div class="panel-title"><h2>人工审核 {{reviewTarget.id.slice(0,8)}}</h2><button @click="reviewTarget=null">关闭</button></div><div class="observation-form"><label>审核动作<select v-model="reviewAction"><option value="confirm">确认可见值</option><option value="correct">纠正错误 / 补充 UNKNOWN</option><option value="reject">识别错误，拒绝</option></select></label><label>可见事实字段<select v-model="reviewField"><option v-for="field in ['visible_text','entry_coordinates','map_name','player_position','monster_name','boss_name','quest_text','item_name','visible_hp','minimum_level','minimum_battle_power','game_build_number']" :key="field">{{field}}</option></select></label><label>审核人<input v-model="reviewer"></label><label>画面依据<input v-model="rationale" placeholder="只能确认此画面确实显示的值"></label><label v-if="reviewAction==='correct'" class="full">纠正值（JSON，如 [850,500]、90 或 &quot;文本&quot;）<textarea v-model="reviewValue"></textarea></label><button :disabled="busy||dataLoading" @click="saveReview">提交人工审核</button><p>官网历史值不会覆盖。SIMULATOR 样本只能形成 SIMULATED_ASSUMPTION。</p></div></section>
<section v-if="evidence" class="panel history"><div class="panel-title"><h2>数据证据详情</h2><button @click="evidence=null">关闭证据</button></div><pre class="evidence-json">{{JSON.stringify(evidence,null,2)}}</pre></section>
<section v-if="page==='#/review'" class="panel history"><div class="panel-title"><h2>已审核可见值与官网冲突</h2><span>{{facts.length}} 条审核事实 · {{conflicts.length}} 项观察冲突</span></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>值</th><th>数据类别</th><th>版本</th><th>有效范围</th></tr></thead><tbody><tr v-for="f in facts" :key="f.id"><td>{{f.field}}</td><td>{{JSON.stringify(f.value)}}</td><td>{{f.data_class}}</td><td>{{f.game_version??'UNKNOWN'}}</td><td>{{f.scope}}</td></tr></tbody></table><div v-for="c in conflicts" :key="c.id" class="notice">{{c.field}} · {{c.status}} · 观察 {{JSON.stringify(c.observed_evidence.value)}} / 官网 {{JSON.stringify(c.official_evidence?.normalized_value)}} <a :href="c.official_evidence?.source_url" target="_blank">官网来源</a><p>{{c.explanation}}</p></div></div></section>
<section v-if="page==='#/twins'" class="panel history twin-panel"><div class="panel-title"><h2>独立九星研究场景配置</h2><span>{{twinRows.length}} 个历史版本</span></div><p>原模拟副本独立运行。研究配置仅记录证据可见值；模拟假设须写 assumption_note 和 execution_environment: SIMULATOR。EVIDENCE_LINKED 仅表示引用校验通过。</p><label>配置 JSON<textarea class="json-editor" v-model="twinEditor" style="min-height:420px"></textarea></label><button class="primary" :disabled="busy||dataLoading" @click="saveTwin">保存场景新版本</button><div v-for="row in twinRows" :key="row.id" class="notice">{{row.scene_id}} · 版本 {{row.revision}} · {{row.configuration.validation_status}} · {{row.configuration.game_version??'UNKNOWN'}} <button @click="editTwin(row)">加载此版本编辑</button><details><summary>配置与证据</summary><pre class="evidence-json">{{JSON.stringify(row,null,2)}}</pre></details></div><details><summary>可引用证据（{{twinEvidence.length}}）</summary><p>条目格式：{data_class, evidence_ids: [证据ID], value: 证据原值}。标注保留坐标体系与可见范围。</p><pre class="evidence-json">{{JSON.stringify(twinEvidence,null,2)}}</pre></details></section>
<section class="panel history"><div class="panel-title"><h2>真实观察事件</h2><span>{{connected?'SSE 已连接':'断线重连中'}}</span></div><div class="logs"><div v-for="e in events" :key="e.id" class="log-line"><time>{{new Date(e.timestamp).toLocaleTimeString()}}</time><b>{{e.level}}</b><span>{{e.eventType}}</span><span>{{e.message}}</span><details><summary>#{{e.id}}</summary>{{e.details}}</details></div><p v-if="!events.length" class="empty">等待真实导入、识别、审核或标注操作</p></div></section><footer>不执行游戏客户端操作 · 所有识别先审核 · 地图完整度与总体识别率尚未测定</footer>
</main></div>
</template>
